  defaultViewport: { width: 2400, height: 1600 }
}\);
const page = await browser.newPage\(\);
await page.setUserAgent\(UA\);
const out = [];
page.on\('request', req => {
  const u = req.url\(\);
  if \(u.includes\('/image/batch'\) || u.includes\('realtime_token'\) || u.includes\('file_metadata'\)\) {
    out.push\('REQ ' + req.method\(\) + ' ' + u + '\\n' + \(req.postData\(\) || ''\).slice\(0, 3000\) + '\\n'\);
  }
}\);
page.on\('response', async res => {
  const u = res.url\(\);
  if \(u.includes\('/image/batch'\) || u.includes\('realtime_token'\) || u.includes\('file_metadata'\)\) {
    try {
      const t = await res.text\(\);
      out.push\('RES ' + res.status\(\) + ' ' + u + '\\n' + t.slice\(0, 5000\) + '\\n'\);
    } catch\(e\) {}
  }
}\);
page.on\('websocket', ws => {
  out.push\('WS OPEN ' + ws.url\(\) + '\\n'\);
