await new Promise\(r => setTimeout\(r, 25000\)\);
fs.writeFileSync\('/tmp/figcap/net2.txt', out.join\('\\n'\)\);
console.log\('bytes', out.join\('\\n'\).length\);
await browser.close\(\);
EOF
